func adminHandler(w http.ResponseWriter, r *http.Request) {
	basePath := r.Context().Value(ctxBasePath).(string)

	user := r.Context().Value(CtxUserKey).(*models.User)
	domain, _ := r.Context().Value(ctxDomain).(*models.Domain)

	if !user.IsSuperAdmin {
		http.Error(w, http.StatusText(403), http.StatusForbidden)
		return
	}

	errMsg := ""

	if r.Method == "POST" {
		if err := r.ParseForm(); err != nil {
			http.Error(w, "Error parsing form.", http.StatusBadRequest)
			return
		}

		forumName := r.PostFormValue("forum_name")
		whitelistedEmailDomains := r.PostFormValue("whitelisted_email_domains")
		logo := r.PostFormValue("logo")
		icon := r.PostFormValue("icon")
		isRegularSignupEnabled := r.PostFormValue("is_regular_signup_enabled") == "1"
		isRegularSigninEnabled := r.PostFormValue("is_regular_signin_enabled") == "1"
		isAutoUserCreationOnEmailSigninEnabled := r.PostFormValue("is_auto_user_creation_on_email_signin_enabled") == "1"
		isReadOnly := r.PostFormValue("is_readonly") == "1"
		isPrivate := r.PostFormValue("is_private") == "1"
		signupToken := r.PostFormValue("signup_token")

		if len(forumName) < 3 || len(forumName) > 30 {
			errMsg = "Forum name should have between 3 and 30 characters"
		}

		if len(signupToken) > 30 {
			errMsg = "Signup token should have fewer than 30 characters"
		}

		for _, r := range signupToken {
			if (r < 'a' || r > 'z') && (r < 'A' || r > 'Z') && (r < '0' || r > '9') && r != '-' {
				errMsg = "Signup token should be alphanumeric"
			}
		}

		if errMsg == "" {
			models.UpdateDomainByID(domain.DomainID,
				forumName,
				whitelistedEmailDomains,
				logo,
				icon,
				isRegularSignupEnabled,
				isRegularSigninEnabled,
				isAutoUserCreationOnEmailSigninEnabled,
				isReadOnly,
				isPrivate,
				signupToken,
			)
			http.Redirect(w, r, basePath+"admin", http.StatusSeeOther)
			return
		}
	}

	mods := models.GetSuperModsByDomainID(domain.DomainID)
	categories := models.GetCategoriesByDomainID(domain.DomainID)

	templates.Admin.Execute(w, map[string]interface{}{
		csrf.TemplateTag: csrf.TemplateField(r),
		BasePathField:    basePath,
		UserField:        user,
		"Domain":         domain,
		"Host":           r.Host,
		"Mods":           mods,
		"Categories":     categories,
		"ErrMsg":         errMsg,
	})
}

func postAuthSignUp(w http.ResponseWriter, r *http.Request) {
	domain := r.Context().Value(ctxDomain).(*models.Domain)
	basePath := r.Context().Value(ctxBasePath).(string)
	next := cleanNextURL(r.FormValue("next"), basePath)
	signupToken := chi.URLParam(r, "signupToken")

	email := r.PostFormValue("email")
	passwd := r.PostFormValue("password")
	passwd2 := r.PostFormValue("password2")

	email = strings.Trim(email, " ")

	if signupToken != "" && signupToken != domain.SignupToken {
		http.Error(w, http.StatusText(404), http.StatusNotFound)
		return
	}

	errMsg := ""

	errMsg = validateEmail(email, domain)

	if len(passwd) < 6 {
		errMsg = "Password should have at least 6 characters"
	} else if passwd != passwd2 {
		errMsg = "Passwords do not match"
	}

	existingUser := models.GetUserByEmail(domain.DomainID, email)
	if existingUser != nil {
		errMsg = "E-mail already registered"
	}

	if !domain.IsRegularSignupEnabled {
		if domain.SignupToken == "" || signupToken == "" || domain.SignupToken != signupToken {
			http.Error(w, "Signup is disabled. Contact the admin.", http.StatusForbidden)
			return
		}
	}

	if errMsg == "" {
		displayName := strings.Split(email, "@")[0]
		displayName = strings.Title(strings.ToLower(displayName))

		err := models.CreateUser(domain.DomainID, email, displayName, passwd)
		if err != nil {
			glog.Errorf("Error creating user: %s", err.Error())
			errMsg = "Error during signup."
		}
	}

	if errMsg == "" {
		glog.Infof("Created user: %s for domainID: %d", email, domain.DomainID)
		user := models.GetUserByEmail(domain.DomainID, email)
		err := authenticate(user.UserID, basePath, w)
		if err != nil {
			glog.Errorf("Error authenticating: %s", err.Error())
		}
		http.Redirect(w, r, next, http.StatusSeeOther)
	}

	templates.Signup.Execute(w, map[string]interface{}{
		csrf.TemplateTag: csrf.TemplateField(r),
		BasePathField:    basePath,
		DomainField:      domain,
		"ErrMsg":         errMsg,
		"Next":           next,
	})
}

func postAuthSignIn(w http.ResponseWriter, r *http.Request) {
	domain := r.Context().Value(ctxDomain).(*models.Domain)
	basePath := r.Context().Value(ctxBasePath).(string)
	next := cleanNextURL(r.FormValue("next"), basePath)
	email := r.PostFormValue("email")
	passwd := r.PostFormValue("password")
	user := models.GetUserByPasswd(domain.DomainID, email, passwd)

	if !domain.IsRegularSigninEnabled {
		http.Error(w, "Signing in with password is disabled. Please use your email to get a one-time signin link.", http.StatusForbidden)
		return
	}

	if user != nil && !user.BannedAt.Valid {
		err := authenticate(user.UserID, basePath, w)
		if err != nil {
			glog.Errorf("Error authenticating: %s", err.Error())
		}
		http.Redirect(w, r, next, http.StatusSeeOther)
	}
	templates.Signin.Execute(w, map[string]interface{}{
		csrf.TemplateTag: csrf.TemplateField(r),
		BasePathField:    basePath,
		DomainField:      domain,
		"Next":           next,
		"ErrMsg":         "Invalid email / password",
	})
}

func editComment(w http.ResponseWriter, r *http.Request) {
	basePath := r.Context().Value(ctxBasePath).(string)

	user, _ := r.Context().Value(CtxUserKey).(*models.User)
	domain := r.Context().Value(ctxDomain).(*models.Domain)

	topicIDStr := chi.URLParam(r, "topicID")
	categoryIDStr := chi.URLParam(r, "categoryID")
	commentIDStr := chi.URLParam(r, "commentID")
	quoteIDStr := r.URL.Query().Get("quote")

	categoryID, err := strconv.Atoi(categoryIDStr)
	if err != nil {
		http.Error(w, http.StatusText(http.StatusBadRequest), http.StatusBadRequest)
		return
	}
	category := models.GetCategoryByID(categoryID)
	if category == nil || category.DomainID != domain.DomainID || category.ArchivedAt.Valid {
		http.Error(w, http.StatusText(http.StatusNotFound), http.StatusNotFound)
		return
	}

	topicID, err := strconv.Atoi(topicIDStr)
	if err != nil {
		http.Error(w, http.StatusText(http.StatusBadRequest), http.StatusBadRequest)
		return
	}
	topic := models.GetTopicByID(topicID)
	if topic.CategoryID != category.CategoryID {
		http.Error(w, http.StatusText(http.StatusNotFound), http.StatusNotFound)
		return
	}

	var comment *models.Comment
	if commentIDStr != "" {
		// Edit comment
		commentID, err := strconv.Atoi(commentIDStr)
		if err != nil {
			http.Error(w, http.StatusText(http.StatusBadRequest), http.StatusBadRequest)
			return
		}
		comment = models.GetCommentByID(commentID)
		if comment == nil || comment.TopicID != topic.TopicID {
			http.Error(w, http.StatusText(http.StatusNotFound), http.StatusNotFound)
			return
		}
	}

	var quote string
	if comment == nil {
		if quoteIDStr == "topic" {
			quote = "> " + strings.ReplaceAll(topic.Content, "\n", "\n> ")
		} else {
			if quoteCommentID, err := strconv.Atoi(quoteIDStr); err == nil {
				if quoteComment := models.GetCommentByID(quoteCommentID); quoteComment != nil {
					if quoteComment.TopicID == topic.TopicID {
						quote = "> " + strings.ReplaceAll(quoteComment.Content, "\n", "\n> ")
					}
				}
			}
		}
	}

	if r.Method == "POST" {
		if err := r.ParseForm(); err != nil {
			http.Error(w, http.StatusText(http.StatusBadRequest), http.StatusBadRequest)
			return
		}
		action := r.PostFormValue("action")
		content := r.PostFormValue("content")
		isSticky := r.PostFormValue("is_sticky") == "1"
		if !(user.IsSuperAdmin || user.IsSuperMod) {
			isSticky = false
			if topic != nil {
				isSticky = topic.IsSticky
			}
		}
		if action == "Submit" {
			if topic.IsReadOnly {
				http.Error(w, http.StatusText(http.StatusForbidden), http.StatusForbidden)
				return
			}
			newCommentID := models.CreateComment(topic.TopicID, user.UserID, content, isSticky)
			if newCommentID >= 0 {
				http.Redirect(w, r, basePath+"categories/"+strconv.Itoa(category.CategoryID)+
					"/topics/"+strconv.Itoa(topic.TopicID)+
					"#comment-"+strconv.Itoa(newCommentID),
					http.StatusSeeOther)
				return
			}
		} else if action == "Update" {
			models.UpdateCommentByID(comment.CommentID, content, isSticky)
			http.Redirect(w, r, basePath+"categories/"+strconv.Itoa(category.CategoryID)+
				"/topics/"+strconv.Itoa(topic.TopicID)+
				"#comment-"+strconv.Itoa(comment.CommentID),
				http.StatusSeeOther)
			return
		} else if action == "Delete" {
			models.DeleteCommentByID(comment.CommentID, comment.UserID, topic.TopicID)
			http.Redirect(w, r, basePath+"categories/"+strconv.Itoa(category.CategoryID)+
				"/topics/"+strconv.Itoa(topic.TopicID),
				http.StatusSeeOther)
			return
		}
		http.Error(w, http.StatusText(http.StatusBadRequest), http.StatusBadRequest)
		return
	}

	templates.CommentEdit.Execute(w, map[string]interface{}{
		csrf.TemplateTag: csrf.TemplateField(r),
		BasePathField:    basePath,
		DomainField:      domain,
		UserField:        user,
		"Category":       category,
		"Topic":          topic,
		"Comment":        comment,
		"Quote":          quote,
	})

}

